<?php
declare(strict_types=1);
require __DIR__.'/platform.php';pl_require_admin();header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');$c=pl_config();$db=pl_db();pl_schema($db,$c['site']);$key=pl_key($c['site'],dirname(__DIR__));$table=pl_table($c['site']);$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pl_check_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('Selecione um contato válido.');$sent=pl_notice($db,$c['site'],(int)$id,$key,$c['notify_to'],$c['brand'],'pl_send',time());$notice=$sent?'Aviso aceito pelo serviço de e-mail.':'Aviso não enviado: já foi aceito, está em andamento ou permanece pendente. Confira a situação abaixo.';}catch(Throwable $e){$error='Não foi possível reenviar. Atualize a página e tente novamente.';}}
if(($_GET['exportar']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="interessados-'.$c['site'].'-'.date('Ymd').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");$headers=['ID','Nome','E-mail','Telefone'];if($c['site']==='medmor')$headers[]='Área de atuação';$headers[]='Cadastro (UTC)';$headers[]='Consentimento (UTC)';fputcsv($out,$headers,';', '"','');$q=$db->query("SELECT id,payload,created_at,consented_at FROM $table ORDER BY id");while($row=$q->fetch(PDO::FETCH_ASSOC)){$d=pl_decrypt($row['payload'],$key);$fields=[$row['id'],$d['nome'],$d['email'],$d['telefone']];if($c['site']==='medmor')$fields[]=$d['area'];$fields[]=$row['created_at'];$fields[]=$row['consented_at'];fputcsv($out,array_map('pl_csv_cell',$fields),';','"','');}fclose($out);exit;
}
$total=(int)$db->query("SELECT COUNT(*) FROM $table")->fetchColumn();$page=max(1,(int)($_GET['pagina']??1));$offset=($page-1)*50;$rows=$db->query("SELECT * FROM $table ORDER BY id DESC LIMIT 50 OFFSET ".$offset)->fetchAll(PDO::FETCH_ASSOC);$csrf=pl_csrf();
?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interessados no lançamento · <?=pl_h($c['brand'])?></title><link rel="stylesheet" href="/pre-lancamento/launch.css?v=20261103-1"><style>.admin-shell{max-width:1360px;margin:auto;padding:30px 24px}.admin-shell h1{font-size:clamp(30px,4vw,48px);line-height:1.1}.admin-toolbar{display:flex;gap:14px;flex-wrap:wrap;margin:25px 0}.admin-toolbar a{width:auto}.admin-shell a{color:var(--accent)}.admin-shell .launch-button{color:var(--buttonText)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:16px}table{width:100%;min-width:850px;border-collapse:collapse}th,td{text-align:left;padding:15px;border-bottom:1px solid var(--line);vertical-align:top;font-size:13px}th{color:var(--accent)}td small{display:block;color:var(--muted)}.retry{padding:9px 11px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--accent);cursor:pointer}.admin-note{color:var(--muted);font-size:13px}.pagination{display:flex;gap:20px;margin-top:22px}</style><body class="launch launch--<?=pl_h($c['site'])?>"><main class="admin-shell"><p class="eyebrow"><?=pl_h($c['brand'])?> · ADMINISTRAÇÃO</p><h1>Interessados no lançamento</h1><p><?=$total?> contato<?=$total===1?'':'s'?> registrado<?=$total===1?'':'s'?>.</p><div class="admin-toolbar"><a class="launch-button" href="?exportar=csv">Exportar contatos em CSV ↗</a><a class="launch-button secondary" style="margin:0" href="<?=pl_h($c['admin'])?>">Voltar ao painel</a></div><p class="admin-note">Novos interesses geram um aviso para <?=pl_h($c['notify_to'])?>. Se o envio falhar, o contato continua salvo e pode ser reenviado abaixo. “Aceito” confirma o recebimento pelo serviço de envio, não a entrega na caixa de entrada.</p><?php if($notice):?><p role="status"><?=pl_h($notice)?></p><?php endif;?><?php if($error):?><p role="alert" class="form-error"><?=pl_h($error)?></p><?php endif;?><div class="table-wrap"><table><thead><tr><th>Contato</th><th>E-mail / telefone</th><?php if($c['site']==='medmor'):?><th>Área de atuação</th><?php endif;?><th>Cadastro</th><th>Aviso administrativo</th></tr></thead><tbody><?php foreach($rows as $row):?><?php try{$d=pl_decrypt($row['payload'],$key);}catch(Throwable){$d=['nome'=>'Contato protegido indisponível','email'=>'','telefone'=>'','area'=>''];}?><tr><td><strong><?=pl_h($d['nome'])?></strong><small>#<?=(int)$row['id']?></small></td><td><?=pl_h($d['email'])?><small><?=pl_h($d['telefone']?:'Telefone não informado')?></small></td><?php if($c['site']==='medmor'):?><td><?=pl_h($d['area'])?></td><?php endif;?><td><?=pl_h((new DateTimeImmutable($row['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Sao_Paulo'))->format('d/m/Y H:i'))?><small>Autorizou o contato</small></td><td><?php if($row['notified_at']):?>Aceito pelo serviço de e-mail<?php else:?>Pendente<form method="post"><input type="hidden" name="csrf" value="<?=pl_h($csrf)?>"><input type="hidden" name="action" value="prelaunch_retry"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="retry">Reenviar aviso</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Os novos interessados aparecerão aqui.</td></tr><?php endif;?></tbody></table></div><nav class="pagination"><?php if($page>1):?><a href="?pagina=<?=$page-1?>">← Anteriores</a><?php endif;?><?php if($offset+50<$total):?><a href="?pagina=<?=$page+1?>">Próximos →</a><?php endif;?></nav><p class="admin-note">O CSV reúne os contatos que autorizaram o aviso de lançamento. Nenhum disparo em massa é iniciado por esta página.</p></main></body></html>
